function Test-MeridianLogSpace {
  param([string]$SqlInstance = "MERSQLPRD01")
  $logSpace = Invoke-DbaQuery -SqlInstance $SqlInstance `
    -Query "DBCC SQLPERF(LOGSPACE)" |
    Where-Object DatabaseName -eq 'MeridianCommerce'
  $pct = $logSpace.'Log Space In Use (%)'
  if ($pct -ge 90) {
    Send-MeridianAlert -Severity Critical -Channel Phone -Message $pct
  } elseif ($pct -ge 70) {
    Send-MeridianAlert -Severity Warning -Channel Teams -Message $pct
  }
}

function Send-MeridianAlert {
  param(
    [ValidateSet('Info','Warning','Critical')]$Severity,
    [ValidateSet('Teams','Phone')]$Channel = 'Teams',
    $Message
  )
  if ($Channel -eq 'Teams') {
    Invoke-RestMethod -Uri $env:MERIDIAN_TEAMS_WEBHOOK -Method Post `
      -Body (@{text="[$Severity] $Message"} | ConvertTo-Json)
  } else {
    Invoke-RestMethod -Uri $env:MERIDIAN_PAGER_WEBHOOK -Method Post `
      -Body (@{message=$Message} | ConvertTo-Json)
  }
}
